package com.api.ai.report;

import com.api.ai.analysis.FailureAnalysisResult;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.io.PrintWriter;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;

/**
 * Generates a static HTML dashboard summarizing AI failure analysis results.
 *
 * Output: target/ai-analysis/ai-dashboard.html
 *
 * The dashboard includes:
 *  - Run summary (generated by RunSummaryGenerator)
 *  - Per-failure cards: scenario, category badge, summary, likely cause, suggested checks
 */
public class AiDashboardWriter {

    private static final Logger logger = LogManager.getLogger(AiDashboardWriter.class);
    private static final String DASHBOARD_FILE = "ai-dashboard.html";

    private AiDashboardWriter() {}

    /**
     * Writes the HTML dashboard to the specified directory.
     *
     * @param outputDir  directory where the dashboard is written (created if absent)
     * @param summary    run-level summary text
     * @param results    list of all analyzed failure results
     */
    public static void write(String outputDir, String summary,
                             List<FailureAnalysisResult> results) {
        File dir = new File(outputDir);
        dir.mkdirs();
        File outFile = new File(dir, DASHBOARD_FILE);

        try (PrintWriter pw = new PrintWriter(new FileWriter(outFile))) {
            pw.println(buildHtml(summary, results));
            logger.info("[AiDashboardWriter] Dashboard written to {}", outFile.getAbsolutePath());
        } catch (IOException e) {
            logger.warn("[AiDashboardWriter] Failed to write dashboard: {}", e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // HTML generation
    // -------------------------------------------------------------------------

    private static String buildHtml(String summary, List<FailureAnalysisResult> results) {
        String timestamp = LocalDateTime.now()
                .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));

        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html lang='en'><head>\n");
        sb.append("<meta charset='UTF-8'/>\n");
        sb.append("<title>AI Test Failure Analysis Dashboard</title>\n");
        sb.append(CSS);
        sb.append("</head><body>\n");

        // Header
        sb.append("<div class='header'>\n");
        sb.append("  <h1>🤖 AI Test Failure Analysis</h1>\n");
        sb.append("  <p class='timestamp'>Generated: ").append(esc(timestamp)).append("</p>\n");
        sb.append("</div>\n");

        // Summary
        sb.append("<div class='summary-box'>\n");
        sb.append("  <h2>Run Summary</h2>\n");
        sb.append("  <p>").append(esc(summary)).append("</p>\n");
        sb.append("</div>\n");

        // Failure cards
        if (results == null || results.isEmpty()) {
            sb.append("<div class='no-failures'>No AI-analyzed failures to display.</div>\n");
        } else {
            sb.append("<div class='cards-container'>\n");
            for (FailureAnalysisResult r : results) {
                sb.append(buildCard(r));
            }
            sb.append("</div>\n");
        }

        sb.append("</body></html>");
        return sb.toString();
    }

    private static String buildCard(FailureAnalysisResult r) {
        String cat        = r.getResolvedCategory() != null ? r.getResolvedCategory().name() : "OTHER";
        String catClass   = "badge badge-" + cat.toLowerCase().replace("_", "-");
        String scenario   = r.getScenario()    != null ? r.getScenario()    : "Unknown";
        String summary    = r.getSummary()      != null ? r.getSummary()     : "-";
        String cause      = r.getLikelyCause()  != null ? r.getLikelyCause() : "-";

        StringBuilder sb = new StringBuilder();
        sb.append("<div class='card'>\n");
        sb.append("  <div class='card-header'>\n");
        sb.append("    <span class='scenario'>").append(esc(scenario)).append("</span>\n");
        sb.append("    <span class='").append(catClass).append("'>").append(esc(cat)).append("</span>\n");
        sb.append("  </div>\n");
        sb.append("  <div class='card-body'>\n");
        sb.append("    <p><strong>Summary:</strong> ").append(esc(summary)).append("</p>\n");
        sb.append("    <p><strong>Likely Cause:</strong> ").append(esc(cause)).append("</p>\n");

        if (r.getSuggestedChecks() != null && !r.getSuggestedChecks().isEmpty()) {
            sb.append("    <p><strong>Suggested Checks:</strong></p><ol>\n");
            for (String check : r.getSuggestedChecks()) {
                sb.append("      <li>").append(esc(check)).append("</li>\n");
            }
            sb.append("    </ol>\n");
        }

        sb.append("  </div>\n");
        sb.append("</div>\n");
        return sb.toString();
    }

    private static String esc(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;");
    }

    // Inline CSS for the dashboard
    private static final String CSS =
        "<style>\n" +
        "  * { box-sizing: border-box; margin: 0; padding: 0; }\n" +
        "  body { font-family: 'Segoe UI', sans-serif; background: #0f172a; color: #e2e8f0; }\n" +
        "  .header { background: linear-gradient(135deg, #1e3a5f, #0f172a); padding: 30px 40px; border-bottom: 1px solid #334155; }\n" +
        "  .header h1 { font-size: 28px; color: #38bdf8; }\n" +
        "  .timestamp { font-size: 13px; color: #94a3b8; margin-top: 6px; }\n" +
        "  .summary-box { background: #1e293b; border-left: 4px solid #38bdf8; margin: 28px 40px; padding: 20px 24px; border-radius: 8px; }\n" +
        "  .summary-box h2 { color: #38bdf8; margin-bottom: 10px; font-size: 18px; }\n" +
        "  .summary-box p { color: #cbd5e1; line-height: 1.6; }\n" +
        "  .cards-container { padding: 0 40px 40px; display: grid; grid-template-columns: repeat(auto-fill, minmax(420px, 1fr)); gap: 20px; }\n" +
        "  .card { background: #1e293b; border: 1px solid #334155; border-radius: 10px; overflow: hidden; transition: transform .15s; }\n" +
        "  .card:hover { transform: translateY(-2px); border-color: #38bdf8; }\n" +
        "  .card-header { display: flex; justify-content: space-between; align-items: center; padding: 14px 18px; background: #0f172a; border-bottom: 1px solid #334155; }\n" +
        "  .scenario { font-weight: 600; color: #f1f5f9; font-size: 14px; max-width: 75%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n" +
        "  .badge { padding: 4px 10px; border-radius: 12px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; }\n" +
        "  .badge-api-contract  { background: #312e81; color: #a5b4fc; }\n" +
        "  .badge-assertion     { background: #1e3a5f; color: #7dd3fc; }\n" +
        "  .badge-auth          { background: #3b0764; color: #d8b4fe; }\n" +
        "  .badge-data-setup    { background: #14532d; color: #86efac; }\n" +
        "  .badge-environment   { background: #431407; color: #fdba74; }\n" +
        "  .badge-timing        { background: #422006; color: #fde68a; }\n" +
        "  .badge-other         { background: #1e293b; color: #94a3b8; border: 1px solid #475569; }\n" +
        "  .card-body { padding: 16px 18px; }\n" +
        "  .card-body p { margin-bottom: 10px; font-size: 14px; color: #cbd5e1; line-height: 1.5; }\n" +
        "  .card-body strong { color: #94a3b8; }\n" +
        "  .card-body ol { padding-left: 20px; margin-top: 6px; }\n" +
        "  .card-body li { font-size: 13px; color: #94a3b8; margin-bottom: 4px; }\n" +
        "  .no-failures { padding: 40px; text-align: center; color: #64748b; font-size: 16px; }\n" +
        "</style>\n";
}
